cd /app && source venv/bin/activate && python3 << 'EOF'
import os
from PIL import Image
import pytesseract
import PyPDF2
import csv
from pathlib import Path

# Create directories
os.makedirs('/app/invoices', exist_ok=True)
os.makedirs('/app/other', exist_ok=True)

# Function to extract text from JPG
def extract_from_jpg(filepath):
    try:
        img = Image.open(filepath)
        text = pytesseract.image_to_string(img)
        return text
    except Exception as e:
        print(f"Error extracting from {filepath}: {e}")
        return ""

# Function to extract text from PDF
def extract_from_pdf(filepath):
    try:
        text = ""
        with open(filepath, 'rb') as f:
            reader = PyPDF2.PdfReader(f)
            for page in reader.pages:
                text += page.extract_text()
        return text
    except Exception as e:
        print(f"Error extracting from {filepath}: {e}")
        return ""

# Classify and extract data
invoices_data = []
documents_dir = '/app/documents'

for filename in sorted(os.listdir(documents_dir)):
    filepath = os.path.join(documents_dir, filename)

    if filename.lower().endswith('.jpg'):
        text = extract_from_jpg(filepath)
    elif filename.lower().endswith('.pdf'):
        text = extract_from_pdf(filepath)
    else:
        continue

    # Classify as invoice or other
    text_lower = text.lower()
    is_invoice = ('invoice' in text_lower or 'amount due' in text_lower or 
                  'total' in text_lower or 'vat' in text_lower or 'tax' in text_lower or 'gst' in text_lower)

    if is_invoice:
        # Extract total_amount
        total_amount = ""
        vat_amount = ""

        # Look for amount patterns
        lines = text.split('\n')
        for i, line in enumerate(lines):
            line_lower = line.lower()

            # Extract VAT/Tax/GST
            if any(term in line_lower for term in ['vat', 'tax', 'gst']):
                # Try to find amount after the term
                parts = line.split()
                for j, part in enumerate(parts):
                    if any(term in part.lower() for term in ['vat', 'tax', 'gst']):
                        # Look for number after this
                        for k in range(j+1, len(parts)):
                            try:
                                val = float(parts[k].replace('$', '').replace(',', '').strip())
                                if val > 0:
                                    vat_amount = str(val)
                                    break
                            except:
                                pass
                        if vat_amount:
                            break

            # Extract Total (prioritize "Total" over "Amount Due")
            if 'total' in line_lower and 'total' not in line_lower.replace('total', ''):
                # This is a line with "Total"
                parts = line.split()
                for j, part in enumerate(parts):
                    if part.lower() in ['total', 'total:']:
                        # Look for number after this
                        for k in range(j+1, len(parts)):
                            try:
                                val = float(parts[k].replace('$', '').replace(',', '').strip())
                                if val > 0:
                                    total_amount = str(val)
                                    break
                            except:
                                pass
                        if total_amount:
                            break

            # Extract Amount Due (only if Total not found)
            if not total_amount and 'amount due' in line_lower:
                parts = line.split()
                for j in range(len(parts)):
                    try:
                        val = float(parts[j].replace('$', '').replace(',', '').strip())
                        if val > 0:
                            total_amount = str(val)
                            break
                    except:
                        pass

        # Move to invoices directory
        new_path = os.path.join('/app/invoices', filename)
        os.rename(filepath, new_path)
        invoices_data.append({
            'filename': filename,
            'total_amount': total_amount,
            'vat_amount': vat_amount
        })
        print(f"Invoice: {filename} - Total: {total_amount}, VAT: {vat_amount}")
    else:
        # Move to other directory
        new_path = os.path.join('/app/other', filename)
        os.rename(filepath, new_path)
        print(f"Other: {filename}")

# Create summary.csv
if invoices_data:
    total_sum = 0
    vat_sum = 0

    with open('/app/invoices/summary.csv', 'w', newline='') as f:
        writer = csv.writer(f)
        writer.writerow(['filename', 'total_amount', 'vat_amount'])

        for item in invoices_data:
            writer.writerow([item['filename'], item['total_amount'], item['vat_amount']])
            try:
                total_sum += float(item['total_amount']) if item['total_amount'] else 0
                vat_sum += float(item['vat_amount']) if item['vat_amount'] else 0
            except:
                pass

        # Add total row
        writer.writerow(['total', total_sum, vat_sum])

    print(f"\nSummary CSV created with {len(invoices_data)} invoices")
    print(f"Total sum: {total_sum}, VAT sum: {vat_sum}")

# Check if documents dir is empty
remaining = os.listdir(documents_dir)
print(f"\nRemaining files in /app/documents: {remaining}")
EOF
